import {getAction} from '@madou/catalog';
import {allCardInstanceIds,createGame,gameStats,transition,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand} from './scenario-tools.js';
export const wolfLanceScenarios={'wolf-ordinary':'a2-p10-r3c1','wolf-dedicated':'a2-p10-r3c1','lance-ordinary':'a2-p10-r3c2','lance-one':'a2-p10-r3c2','lance-two':'a2-p10-r3c2'} as const;
export type WolfLanceScenario=keyof typeof wolfLanceScenarios;
export function isWolfLanceScenario(name:string):name is WolfLanceScenario{return Object.hasOwn(wolfLanceScenarios,name);}
export function makeWolfLanceScenario(name:WolfLanceScenario,players:{id:string;name:string}[],options:{level?:number;approach?:boolean;follower?:boolean;owner?:string}={}){
 let s=createGame(players,entropy(),{startingSeat:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];assignCharacter(s,a,options.owner??(name.startsWith('wolf')?'餓狼ヨーツルム':'早駆けのランカスター'));assignCharacter(s,b,'黒騎士ガーウィン');assignCharacter(s,c,'大神官ジル');assignCharacter(s,d,'魔導王ガイナス');for(const p of Object.values(s.players))p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};const stats=gameStats(s,a);s.players[a]!.permanent!.warrior_level=20+(options.level??5)-stats.warrior_level;s.players[a]!.permanent!.spirit=20+6-stats.spirit;
 const card=takeCard(s,a,wolfLanceScenarios[name]),advance=takeCard(s,a,'a2-p24-r1c2'),first=takeCard(s,b,'a2-p07-r1c1'),second=takeCard(s,b,'a2-p07-r1c2'),fate=takeCard(s,c,'命運凶変'),soldier=options.follower?takeCard(s,b,'兵士'):null;trimHand(s,a,card,advance);trimHand(s,b,first,second,...(soldier?[soldier]:[]));trimHand(s,c,fate);s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];
 function act(actorId:string,command:GameCommand){const input={actorId,command},e=entropy(),r=transition(s,input,e);if(!r.ok)throw Error(`WOLF_LANCE_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('WOLF_LANCE_FIXTURE_JSON');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('WOLF_LANCE_FIXTURE_IDS');}
 act(a,{type:'PASS_SETUP'});if(soldier)act(b,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:soldier});for(const id of [b,c,d])act(id,{type:'PASS_SETUP'});act(a,{type:'START_TURN'});act(a,{type:'CHOOSE_DRAW',draw:false});if(name==='wolf-ordinary'&&options.approach!==false){act(a,{type:'APPROACH',targetId:b,cardInstanceId:advance});for(let n=0;n<100&&s.windows?.length;n++){const w=s.windows.at(-1)!;act(w.participants[w.cursor]!,{type:'PASS'});}}return s;
}
